//! The `LocOpe_Pipe` constructor body (`LocOpe_Pipe.cxx:51-273`): drop the
//! faces generated by the profile's connectivity edges, then fuse the
//! coplanar faces swept from one profile edge.
//!
//! Everything here is a branch-for-branch translation of the reference. The
//! only non-direct correspondences are the `NCollection_Map` iterations, which
//! OCCT walks in hash-bucket order while the port walks insertion order (see
//! `locope::shape_maps`), and `TopoDS_Shape::IsNull`, which the port answers
//! through a slot that the reference only ever leaves empty for a degenerated
//! profile edge (`BRepFill_Pipe.cxx:376-379`).

use std::sync::Arc;

use occt_core::precision::{ANGULAR, CONFUSION};
use occt_core::gp::GpPln;
use occt_geom::Surface;

use crate::abs::{Orientation, ShapeType};
use crate::brep_fill_pipe::Pipe as BRepFillPipe;
use crate::brep_tool::BRepTool;
use crate::builder::TopoBuilder;
use crate::locope::build_shape::BuildShape;
use crate::locope::shape_maps::{ShapeSet, ShapeValueMap};
use crate::shape::{Edge, Face, TopoShape, Wire};
use crate::topo_tools::{explorer_shapes, is_same, AncestorMap};

/// `LocOpe_Pipe::LocOpe_Pipe(Spine, Profile)` (`cxx:51-273`) minus the
/// `BRepFill_Pipe` construction: answers `myMap` and `myRes`.
pub(super) fn fuse_faces(
    pipe: &BRepFillPipe,
    spine: &Wire,
    profile: &TopoShape,
) -> Result<(ShapeValueMap<Vec<TopoShape>>, Option<TopoShape>), String> {
    // `cxx:56`.
    let result = pipe
        .shape()
        .cloned()
        .ok_or_else(|| "StdFail_NotDone: BRepFill_Pipe::Shape".to_string())?;

    // `cxx:60-61`: `TopExp::MapShapesAndAncestors(Profile, EDGE, FACE, theEFMap)`.
    let the_ef_map = AncestorMap::map_shapes_and_ancestors(profile, ShapeType::Edge, ShapeType::Face);
    // `cxx:62-63`.
    let mut my_map: ShapeValueMap<Vec<TopoShape>> = ShapeValueMap::new();
    let mut good_faces: Vec<TopoShape> = Vec::new();
    // `cxx:64`: the single `TopExp_Explorer exp` is re-`Init`ed per loop; the
    // port keeps the spine's edge list once instead.
    let spine_edges = explorer_shapes(&spine.0, ShapeType::Edge);

    // `cxx:68-69`.
    for i in 1..=the_ef_map.length() {
        let edgpr_top = the_ef_map.find_key(i).clone();
        // `cxx:71-72`: `myMap.Bind(edgpr, Empty)`.
        my_map.bind(&edgpr_top, Vec::new());
        // `cxx:73-77`: "on ne prend pas les faces generees".
        if the_ef_map.ancestors(i).len() >= 2 {
            continue;
        }
        let edgpr = Edge::wrap(edgpr_top.clone())
            .ok_or_else(|| "Standard_TypeMismatch: LocOpe_Pipe".to_string())?;

        // `cxx:79-80`.
        let mut map_fac = ShapeSet::new();
        // `cxx:81-82`.
        for edgsp_top in &spine_edges {
            let edgsp = Edge::wrap(edgsp_top.clone())
                .ok_or_else(|| "Standard_TypeMismatch: LocOpe_Pipe".to_string())?;
            // `cxx:84-87`: `BRepFill_Pipe::Face` answers a null face for a
            // degenerated profile edge (`BRepFill_Pipe.cxx:376-379`) and the
            // reference's `if (!resfac.IsNull())` skips it.
            if BRepTool::is_degenerated(&edgpr) {
                continue;
            }
            let resfac = pipe.face(&edgsp, &edgpr)?;
            // `cxx:88-91`.
            let surface = BRepTool::face_surface(&resfac)
                .ok_or_else(|| "LocOpe_Pipe: swept face without surface".to_string())?;
            let surface = unwrap_trimmed(surface);
            // `cxx:92-101`.
            if surface.gp_pln().is_some() {
                map_fac.add(&resfac.0);
            } else {
                if let Some(list) = my_map.change(&edgpr_top) {
                    list.push(resfac.0.clone());
                }
                good_faces.push(resfac.0.clone());
            }
        }

        // `cxx:107-115`: "un seul plan, rien a faire".
        if map_fac.extent() <= 1 {
            if map_fac.extent() == 1 {
                let key = map_fac.iter()[0].clone();
                if let Some(list) = my_map.change(&edgpr_top) {
                    list.push(key.clone());
                }
                good_faces.push(key);
            }
            continue;
        }

        // `cxx:116`: "chercher les composantes connexes avec meme support".
        while map_fac.extent() >= 2 {
            // `cxx:118-121`: the map iterator restarts from the current first
            // face on every pass.
            let face_ref = Face::wrap(map_fac.iter()[0].clone())
                .ok_or_else(|| "Standard_TypeMismatch: LocOpe_Pipe".to_string())?;
            let mut fac_fuse: Vec<TopoShape> = vec![face_ref.0.clone()];
            // `cxx:124-129`.
            let (_, pl_ref) = basis_plane(&face_ref)?;

            // `cxx:131-144`: the faces of `MapFac` with the same plane support.
            for key in map_fac.iter()[1..].to_vec() {
                let face = Face::wrap(key)
                    .ok_or_else(|| "Standard_TypeMismatch: LocOpe_Pipe".to_string())?;
                let (_, pl) = basis_plane(&face)?;
                if pl.axis().is_parallel_tol(&pl_ref.axis(), ANGULAR)
                    && pl_ref.contains_pnt(&pl.location(), CONFUSION)
                {
                    fac_fuse.push(face.0);
                }
            }

            // `cxx:149`: "FacFuse contient des faces de meme support".
            while fac_fuse.len() >= 2 {
                // `cxx:151-153`.
                let face_ref = Face::wrap(fac_fuse[0].clone())
                    .ok_or_else(|| "Standard_TypeMismatch: LocOpe_Pipe".to_string())?;
                let or_ref = orientation(&face_ref.0, &result)?;
                // `cxx:155-160`.
                let (p_ref, pl_ref) = basis_plane(&face_ref)?;
                let mut dir_ref = pl_ref.axis().direction().clone();
                if (pl_ref.is_direct() && or_ref == Orientation::Reversed)
                    || (!pl_ref.is_direct() && or_ref == Orientation::Forward)
                {
                    dir_ref.reverse();
                }

                // `cxx:168-172`: the edges of the reference face, forward.
                let mut map_ed = ShapeSet::new();
                for edge in explorer_shapes(
                    &face_ref.0.oriented(Orientation::Forward),
                    ShapeType::Edge,
                ) {
                    map_ed.add(&edge);
                }

                // `cxx:174-175`.
                map_fac.remove(&face_ref.0);
                fac_fuse.remove(0);

                // `cxx:176-177`.
                let mut face_to_fuse = false;

                // `cxx:179-231`: the do/while loop.
                loop {
                    // `cxx:180-181`.
                    let mut more_found = false;
                    let mut found_at: Option<usize> = None;
                    // `cxx:182-196`.
                    for (idx, candidate) in fac_fuse.iter().enumerate() {
                        let mut shared = false;
                        for edge in explorer_shapes(candidate, ShapeType::Edge) {
                            if map_ed.contains(&edge) {
                                shared = true;
                                break;
                            }
                        }
                        // `cxx:191-194`: the outer loop breaks once the inner
                        // explorer still has the edge it matched.
                        if shared {
                            more_found = true;
                            found_at = Some(idx);
                            break;
                        }
                    }
                    if !more_found {
                        break;
                    }
                    let idx = found_at.expect("more_found implies a match");
                    // `cxx:199-200`.
                    let fac = Face::wrap(fac_fuse[idx].clone())
                        .ok_or_else(|| "Standard_TypeMismatch: LocOpe_Pipe".to_string())?;
                    let mut or_relat = orientation(&fac.0, &result)?;
                    // `cxx:202-209`.
                    let (_, pl) = basis_plane(&fac)?;
                    let mut dir_pl = pl.axis().direction().clone();
                    if (pl.is_direct() && or_relat == Orientation::Reversed)
                        || (!pl_ref.is_direct() && or_relat == Orientation::Forward)
                    {
                        dir_pl.reverse();
                    }
                    // `cxx:212-220`.
                    or_relat = if dir_pl.dot(&dir_ref) > 0.0 {
                        Orientation::Forward
                    } else {
                        Orientation::Reversed
                    };
                    // `cxx:221-228`: XOR the edges into `MapEd`.
                    for edge in explorer_shapes(&fac.0.oriented(or_relat), ShapeType::Edge) {
                        if !map_ed.add(&edge) {
                            map_ed.remove(&edge);
                        }
                    }
                    // `cxx:229-230`.
                    map_fac.remove(&fac.0);
                    fac_fuse.remove(idx);
                    face_to_fuse = true;
                }

                // `cxx:233-252`: rebuild the fused face on the reference's
                // (untrimmed) surface.
                if face_to_fuse {
                    let builder = TopoBuilder::new();
                    // `cxx:238`: `B.MakeFace(NewFace, P, BRep_Tool::Tolerance(FaceRef))`.
                    let tol = BRepTool::face_tolerance(&face_ref);
                    let mut edges: Vec<Edge> = Vec::with_capacity(map_ed.extent());
                    for key in map_ed.iter() {
                        edges.push(Edge::wrap(key.clone()).ok_or_else(|| {
                            "Standard_TypeMismatch: LocOpe_Pipe".to_string()
                        })?);
                    }
                    let mut new_wire = builder.make_wire(&edges);
                    // `cxx:245-247`: the new wire takes the orientation of the
                    // reference face's first wire.
                    if let Some(wire) = explorer_shapes(
                        &face_ref.0.oriented(Orientation::Forward),
                        ShapeType::Wire,
                    )
                    .first()
                    {
                        new_wire.0.set_orientation(wire.orientation());
                    }
                    let new_face =
                        builder.make_face_with_tolerance(p_ref, &[new_wire], tol);
                    // `cxx:249-250`.
                    if let Some(list) = my_map.change(&edgpr_top) {
                        list.push(new_face.0.clone());
                    }
                    good_faces.push(new_face.0.clone());
                }
            }

            // `cxx:253-258`: the last face of the component is kept as is.
            if fac_fuse.len() == 1 {
                map_fac.remove(&fac_fuse[0]);
                if let Some(list) = my_map.change(&edgpr_top) {
                    list.push(fac_fuse[0].clone());
                }
                good_faces.push(fac_fuse[0].clone());
            }
        }
    }

    // `cxx:263-270`: the sweep's first and last caps.
    if let Some(first) = pipe.first_shape() {
        for face in explorer_shapes(first, ShapeType::Face) {
            good_faces.push(face);
        }
    }
    if let Some(last) = pipe.last_shape() {
        for face in explorer_shapes(last, ShapeType::Face) {
            good_faces.push(face);
        }
    }

    // `cxx:272-273`: `LocOpe_BuildShape BS(goodfaces); myRes = BS.Shape();`.
    let mut build_shape = BuildShape::new();
    build_shape.with_faces(&good_faces)?;
    Ok((my_map, build_shape.shape().cloned()))
}

/// `P = BRep_Tool::Surface(...)` followed by the `Geom_RectangularTrimmedSurface`
/// unwrap (`cxx:88-91`, `:124-128`, `:134-138`, `:155-159`, `:202-206`).
fn unwrap_trimmed(surface: Arc<dyn Surface>) -> Arc<dyn Surface> {
    surface.rectangular_trimmed_basis().unwrap_or(surface)
}

/// The (unwrapped) surface of a swept face together with its plane
/// (`cxx:124-129`, `:155-160`, `:202-207`); `MapFac` only ever holds faces
/// whose surface is a `Geom_Plane` (`cxx:92-96`).
fn basis_plane(face: &Face) -> Result<(Arc<dyn Surface>, GpPln), String> {
    let surface = BRepTool::face_surface(face)
        .ok_or_else(|| "LocOpe_Pipe: swept face without surface".to_string())?;
    let surface = unwrap_trimmed(surface);
    let pln = surface
        .gp_pln()
        .ok_or_else(|| "Standard_TypeMismatch: LocOpe_Pipe expects a Geom_Plane".to_string())?;
    Ok((surface, pln))
}

/// The file-local static `Orientation(Sub, S)` (`cxx:434-443`): the first
/// occurrence of `Sub` in `S`, or the reference's `Standard_NoSuchObject`.
fn orientation(sub: &TopoShape, s: &TopoShape) -> Result<Orientation, String> {
    for shape in explorer_shapes(s, sub.shape_type()) {
        if is_same(&shape, sub) {
            return Ok(shape.orientation());
        }
    }
    Err("Standard_NoSuchObject: LocOpe_Pipe::Orientation".to_string())
}
